for update

select 
from market_order
where buyer_user_id = #{buyerUserId, jdbcType=BINARY}
order by create_time desc, order_id desc
limit #{limit} offset #{offset}

select 
from market_order
where seller_user_id = #{sellerUserId, jdbcType=BINARY}
order by create_time desc, order_id desc
limit #{limit} offset #{offset}

select 
from market_order
where status in ('DELIVERED', 'SHIPPED')
  and auto_confirm_at is not null
  and auto_confirm_at <= #{asOf}
  and auto_confirm_next_attempt_at is not null
  and auto_confirm_next_attempt_at <= #{asOf}
order by auto_confirm_next_attempt_at asc, order_id asc
limit #{limit}

mapper.update:
update market_order
set auto_confirm_next_attempt_at = #{nextAttemptAt},
    update_time = current_timestamp
where order_id = #{orderId, jdbcType=BINARY}
  and status in ('DELIVERED', 'SHIPPED')
  and auto_confirm_at is not null
  and auto_confirm_at <= #{asOf}
  and auto_confirm_next_attempt_at is not null
  and auto_confirm_next_attempt_at <= #{asOf}
